namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}

public class ShipmentSummary
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAtUtc { get; set; }
    public DateTime? EstimatedDeliveryUtc { get; set; }
}

public class ShipmentDetail
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAtUtc { get; set; }
    public DateTime? EstimatedDeliveryUtc { get; set; }
    public string? RecipientName { get; set; }
    public double WeightKg { get; set; }
    public List<TrackingEvent> Events { get; set; } = [];
}

public class TrackingEvent
{
    public DateTime TimestampUtc { get; set; }
    public string Location { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class UpdateShipmentStatusRequest
{
    public ShipmentStatus NewStatus { get; set; }
    public string Location { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<ShipmentSummary>> GetShipmentsAsync(string? statusFilter = null);
    Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<ShipmentDetail?> GetShipmentByIdAsync(int id);
    Task UpdateStatusAsync(int id, UpdateShipmentStatusRequest request);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

/// <summary>
/// Client-side implementation that calls server APIs via HttpClient.
/// Used when running in WebAssembly.
/// </summary>
public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync(string? statusFilter = null)
    {
        var url = "api/shipments";
        if (!string.IsNullOrEmpty(statusFilter))
            url += $"?status={Uri.EscapeDataString(statusFilter)}";

        return await http.GetFromJsonAsync<List<ShipmentSummary>>(url) ?? [];
    }

    public async Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await http.GetFromJsonAsync<ShipmentDetail?>($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
    }

    public async Task<ShipmentDetail?> GetShipmentByIdAsync(int id)
    {
        return await http.GetFromJsonAsync<ShipmentDetail?>($"api/shipments/{id}");
    }

    public async Task UpdateStatusAsync(int id, UpdateShipmentStatusRequest request)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{id}/status", request);
        response.EnsureSuccessStatusCode();
    }
}

