using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side implementation that accesses the database directly.
/// Used when running via Interactive Server render mode.
/// </summary>
public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync(string? statusFilter = null)
    {
        var query = db.Shipments.AsQueryable();

        if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, true, out var status))
        {
            query = query.Where(s => s.Status == status);
        }

        return await query
            .OrderByDescending(s => s.CreatedAtUtc)
            .Select(s => new ShipmentSummary
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = s.Status,
                CreatedAtUtc = s.CreatedAtUtc,
                EstimatedDeliveryUtc = s.EstimatedDeliveryUtc
            })
            .ToListAsync();
    }

    public async Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await db.Shipments
            .Include(s => s.Events)
            .Where(s => s.TrackingNumber == trackingNumber)
            .Select(s => ToDetail(s))
            .FirstOrDefaultAsync();
    }

    public async Task<ShipmentDetail?> GetShipmentByIdAsync(int id)
    {
        return await db.Shipments
            .Include(s => s.Events)
            .Where(s => s.Id == id)
            .Select(s => ToDetail(s))
            .FirstOrDefaultAsync();
    }

    public async Task UpdateStatusAsync(int id, UpdateShipmentStatusRequest request)
    {
        var shipment = await db.Shipments.Include(s => s.Events).FirstOrDefaultAsync(s => s.Id == id)
            ?? throw new InvalidOperationException($"Shipment {id} not found.");

        shipment.Status = request.NewStatus;
        shipment.Events.Add(new TrackingEventEntity
        {
            TimestampUtc = DateTime.UtcNow,
            Location = request.Location,
            Description = request.Description
        });

        await db.SaveChangesAsync();
    }

    private static ShipmentDetail ToDetail(ShipmentEntity s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        CreatedAtUtc = s.CreatedAtUtc,
        EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
        RecipientName = s.RecipientName,
        WeightKg = s.WeightKg,
        Events = s.Events
            .OrderByDescending(e => e.TimestampUtc)
            .Select(e => new TrackingEvent
            {
                TimestampUtc = e.TimestampUtc,
                Location = e.Location,
                Description = e.Description
            })
            .ToList()
    };
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (string? status, IShipmentService svc) =>
            Results.Ok(await svc.GetShipmentsAsync(status)));

        group.MapGet("/{id:int}", async (int id, IShipmentService svc) =>
        {
            var shipment = await svc.GetShipmentByIdAsync(id);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        // Tracking endpoint is public — customers use it without logging in
        app.MapGet("api/shipments/track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
        {
            var shipment = await svc.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        }).AllowAnonymous();

        group.MapPut("/{id:int}/status", async (int id, UpdateShipmentStatusRequest request, IShipmentService svc) =>
        {
            await svc.UpdateStatusAsync(id, request);
            return Results.NoContent();
        });
    }
}

