@page "/track/{TrackingNumber}"

@inject IShipmentService ShipmentService

<PageTitle>Track — @TrackingNumber</PageTitle>

<h2>📍 Tracking: @TrackingNumber</h2>

@if (loading)
{
    <p class="text-muted">Loading shipment details…</p>
}
else if (shipment is null)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number <code>@TrackingNumber</code>.
    </div>
    <a href="/" class="btn btn-outline-primary">← Try another tracking number</a>
}
else
{
    <div class="row mb-4">
        <div class="col-md-6">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Shipment Details</h5>
                    <dl class="row mb-0">
                        <dt class="col-sm-5">Status</dt>
                        <dd class="col-sm-7"><span class="badge @StatusBadgeClass">@shipment.Status</span></dd>
                        <dt class="col-sm-5">Origin</dt>
                        <dd class="col-sm-7">@shipment.Origin</dd>
                        <dt class="col-sm-5">Destination</dt>
                        <dd class="col-sm-7">@shipment.Destination</dd>
                        <dt class="col-sm-5">Recipient</dt>
                        <dd class="col-sm-7">@(shipment.RecipientName ?? "—")</dd>
                        <dt class="col-sm-5">Weight</dt>
                        <dd class="col-sm-7">@shipment.WeightKg.ToString("F1") kg</dd>
                        <dt class="col-sm-5">Created</dt>
                        <dd class="col-sm-7">@shipment.CreatedAtUtc.ToString("yyyy-MM-dd HH:mm") UTC</dd>
                        <dt class="col-sm-5">Est. Delivery</dt>
                        <dd class="col-sm-7">
                            @(shipment.EstimatedDeliveryUtc?.ToString("yyyy-MM-dd HH:mm") ?? "—") UTC
                        </dd>
                    </dl>
                </div>
            </div>
        </div>

        <div class="col-md-6">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Tracking History</h5>
                    @if (shipment.Events.Count == 0)
                    {
                        <p class="text-muted">No events yet.</p>
                    }
                    else
                    {
                        <ul class="list-group list-group-flush">
                            @foreach (var evt in shipment.Events)
                            {
                                <li class="list-group-item px-0">
                                    <strong>@evt.TimestampUtc.ToString("MMM dd, HH:mm") UTC</strong>
                                    — @evt.Location<br />
                                    <small class="text-muted">@evt.Description</small>
                                </li>
                            }
                        </ul>
                    }
                </div>
            </div>
        </div>
    </div>

    <a href="/" class="btn btn-outline-primary">← Track another shipment</a>
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = string.Empty;

    private ShipmentDetail? shipment;
    private bool loading = true;

    protected override async Task OnParametersSetAsync()
    {
        loading = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(TrackingNumber);
        loading = false;
    }

    private string StatusBadgeClass => shipment?.Status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-warning text-dark"
    };
}

@page "/shipments"
@attribute [Authorize]

@inject IShipmentService ShipmentService

<PageTitle>Dispatcher — Shipments</PageTitle>

<h2>📋 Shipments</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <label class="form-label">Filter by Status</label>
        <select class="form-select" @bind="selectedStatus" @bind:after="LoadShipments">
            <option value="">All</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
</div>

@if (loading)
{
    <p class="text-muted">Loading shipments…</p>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Created</th>
                    <th>Est. Delivery</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in shipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @BadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.CreatedAtUtc.ToString("yyyy-MM-dd")</td>
                        <td>@(s.EstimatedDeliveryUtc?.ToString("yyyy-MM-dd") ?? "—")</td>
                        <td>
                            <a class="btn btn-sm btn-outline-primary" href="/shipments/@s.Id">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentSummary> shipments = [];
    private string selectedStatus = string.Empty;
    private bool loading = true;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetShipmentsAsync(
            string.IsNullOrEmpty(selectedStatus) ? null : selectedStatus);
        loading = false;
    }

    private static string BadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-warning text-dark"
    };
}

@page "/shipments/{Id:int}"
@attribute [Authorize]

@inject IShipmentService ShipmentService
@inject NavigationManager Nav

<PageTitle>Shipment Details</PageTitle>

@if (loading)
{
    <p class="text-muted">Loading…</p>
}
else if (shipment is null)
{
    <div class="alert alert-warning">Shipment not found.</div>
    <a href="/shipments" class="btn btn-outline-primary">← Back to list</a>
}
else
{
    <h2>Shipment: <code>@shipment.TrackingNumber</code></h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Details</h5>
                    <dl class="row mb-0">
                        <dt class="col-sm-5">Status</dt>
                        <dd class="col-sm-7"><span class="badge @StatusBadge">@shipment.Status</span></dd>
                        <dt class="col-sm-5">Origin</dt>
                        <dd class="col-sm-7">@shipment.Origin</dd>
                        <dt class="col-sm-5">Destination</dt>
                        <dd class="col-sm-7">@shipment.Destination</dd>
                        <dt class="col-sm-5">Recipient</dt>
                        <dd class="col-sm-7">@(shipment.RecipientName ?? "—")</dd>
                        <dt class="col-sm-5">Weight</dt>
                        <dd class="col-sm-7">@shipment.WeightKg.ToString("F1") kg</dd>
                        <dt class="col-sm-5">Est. Delivery</dt>
                        <dd class="col-sm-7">@(shipment.EstimatedDeliveryUtc?.ToString("yyyy-MM-dd HH:mm") ?? "—") UTC</dd>
                    </dl>
                </div>
            </div>
        </div>

        <div class="col-md-6">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Update Status</h5>
                    <div class="mb-2">
                        <label class="form-label">New Status</label>
                        <select class="form-select" @bind="newStatus">
                            @foreach (var s in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@s">@s</option>
                            }
                        </select>
                    </div>
                    <div class="mb-2">
                        <label class="form-label">Location</label>
                        <input type="text" class="form-control" @bind="updateLocation" placeholder="City, Country" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label">Description</label>
                        <input type="text" class="form-control" @bind="updateDescription" placeholder="What happened?" />
                    </div>
                    <button class="btn btn-primary" @onclick="SubmitStatusUpdate" disabled="@updating">
                        @(updating ? "Updating…" : "Update Status")
                    </button>
                    @if (updateSuccess)
                    {
                        <span class="text-success ms-2">✓ Updated</span>
                    }
                </div>
            </div>
        </div>
    </div>

    <h4>Tracking History</h4>
    @if (shipment.Events.Count == 0)
    {
        <p class="text-muted">No events yet.</p>
    }
    else
    {
        <ul class="list-group mb-4">
            @foreach (var evt in shipment.Events)
            {
                <li class="list-group-item">
                    <strong>@evt.TimestampUtc.ToString("MMM dd, HH:mm") UTC</strong> — @evt.Location<br />
                    <small class="text-muted">@evt.Description</small>
                </li>
            }
        </ul>
    }

    <a href="/shipments" class="btn btn-outline-secondary">← Back to shipments</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private ShipmentDetail? shipment;
    private bool loading = true;
    private bool updating;
    private bool updateSuccess;

    private ShipmentStatus newStatus;
    private string updateLocation = string.Empty;
    private string updateDescription = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        loading = true;
        shipment = await ShipmentService.GetShipmentByIdAsync(Id);
        if (shipment is not null)
            newStatus = shipment.Status;
        loading = false;
    }

    private async Task SubmitStatusUpdate()
    {
        if (shipment is null) return;

        updating = true;
        updateSuccess = false;

        await ShipmentService.UpdateStatusAsync(shipment.Id, new UpdateShipmentStatusRequest
        {
            NewStatus = newStatus,
            Location = updateLocation,
            Description = updateDescription
        });

        // Reload to show new event
        shipment = await ShipmentService.GetShipmentByIdAsync(Id);
        updateLocation = string.Empty;
        updateDescription = string.Empty;
        updating = false;
        updateSuccess = true;
    }

    private string StatusBadge => shipment?.Status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-warning text-dark"
    };
}

